<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 500">
  <!-- Gradient Background -->
  <defs>
    <radialGradient id="backgroundGradient" cx="50%" cy="50%" r="70%" fx="50%" fy="50%">
      <stop offset="0%" stop-color="#D6E4EA" />
      <stop offset="100%" stop-color="#8FA9BA" />
    </radialGradient>
    <radialGradient id="sunGradient" cx="50%" cy="50%" r="70%" fx="40%" fy="40%">
      <stop offset="0%" stop-color="#FFF0BB" />
      <stop offset="80%" stop-color="#E9C06D" />
      <stop offset="100%" stop-color="#D6AE56" />
    </radialGradient>
    <filter id="glow" x="-30%" y="-30%" width="160%" height="160%">
      <feGaussianBlur stdDeviation="10" result="blur" />
      <feComposite in="SourceGraphic" in2="blur" operator="over" />
    </filter>
    <filter id="honeyGlow" x="-20%" y="-20%" width="140%" height="140%">
      <feGaussianBlur stdDeviation="3" result="blur" />
      <feComposite in="SourceGraphic" in2="blur" operator="over" />
    </filter>
    <pattern id="honeyPattern" patternUnits="userSpaceOnUse" width="60" height="60" patternTransform="rotate(30)">
      <path d="M0,30 L15,0 L45,0 L60,30 L45,60 L15,60 Z" fill="none" stroke="#D7B96A" stroke-width="1" opacity="0.2" />
    </pattern>
  </defs>

  <!-- Background -->
  <rect width="500" height="500" fill="url(#backgroundGradient)" />
  <rect width="500" height="500" fill="url(#honeyPattern)" />
  
  <!-- Sun-like center -->
  <circle cx="250" cy="250" r="100" fill="url(#sunGradient)" stroke="#3F2E23" stroke-width="5" filter="url(#glow)" />
  
  <!-- Radiating Ice-Like Beams -->
  <g stroke="#6D91B0" stroke-width="5" opacity="0.7">
    <line x1="250" y1="30" x2="250" y2="150" />
    <line x1="250" y1="350" x2="250" y2="470" />
    <line x1="30" y1="250" x2="150" y2="250" />
    <line x1="350" y1="250" x2="470" y2="250" />
    <line x1="80" y1="80" x2="180" y2="180" />
    <line x1="320" y1="80" x2="420" y2="180" />
    <line x1="80" y1="420" x2="180" y2="320" />
    <line x1="320" y1="420" x2="420" y2="320" />
  </g>
  
  <!-- Honeycomb Elements with animation -->
  <g filter="url(#honeyGlow)">
    <polygon points="200,150 250,120 300,150 300,200 250,230 200,200" fill="#F8E0A7" stroke="#3F2E23" stroke-width="3">
      <animate attributeName="opacity" values="0.8;1;0.8" dur="5s" repeatCount="indefinite" />
    </polygon>
    <polygon points="150,250 200,220 250,250 250,300 200,330 150,300" fill="#F4D7A8" stroke="#3F2E23" stroke-width="3">
      <animate attributeName="opacity" values="0.9;1;0.9" dur="4s" repeatCount="indefinite" begin="1s" />
    </polygon>
    <polygon points="300,250 350,220 400,250 400,300 350,330 300,300" fill="#EEDCAB" stroke="#3F2E23" stroke-width="3">
      <animate attributeName="opacity" values="0.85;1;0.85" dur="6s" repeatCount="indefinite" begin="2s" />
    </polygon>
    <!-- Additional honeycombs -->
    <polygon points="225,300 275,270 325,300 325,350 275,380 225,350" fill="#F1D49F" stroke="#3F2E23" stroke-width="3">
      <animate attributeName="opacity" values="0.85;1;0.85" dur="5s" repeatCount="indefinite" begin="1.5s" />
    </polygon>
    <polygon points="225,120 275,90 325,120 325,170 275,200 225,170" fill="#F6D69D" stroke="#3F2E23" stroke-width="3">
      <animate attributeName="opacity" values="0.9;1;0.9" dur="7s" repeatCount="indefinite" begin="0.5s" />
    </polygon>
  </g>
  
  <!-- Abstract Bee Elements with wings and stripes -->
  <g>
    <!-- First bee -->
    <g transform="rotate(30, 120, 150)">
      <ellipse cx="120" cy="150" rx="20" ry="35" fill="#3F2E23" />
      <!-- Wings -->
      <ellipse cx="105" cy="140" rx="15" ry="10" fill="#FFFFFF" fill-opacity="0.7" stroke="#D6D6D6" stroke-width="1" />
      <ellipse cx="135" cy="140" rx="15" ry="10" fill="#FFFFFF" fill-opacity="0.7" stroke="#D6D6D6" stroke-width="1" />
      <!-- Stripes -->
      <rect x="110" y="135" width="20" height="5" fill="#F4D7A8" />
      <rect x="110" y="145" width="20" height="5" fill="#F4D7A8" />
      <rect x="110" y="155" width="20" height="5" fill="#F4D7A8" />
      <!-- Flight path -->
      <path d="M120,120 Q140,100 160,105 T190,90" fill="none" stroke="#3F2E23" stroke-width="1.5" stroke-dasharray="2,2" />
    </g>
    
    <!-- Second bee -->
    <g transform="rotate(-30, 380, 350)">
      <ellipse cx="380" cy="350" rx="20" ry="35" fill="#3F2E23" />
      <!-- Wings -->
      <ellipse cx="365" cy="340" rx="15" ry="10" fill="#FFFFFF" fill-opacity="0.7" stroke="#D6D6D6" stroke-width="1" />
      <ellipse cx="395" cy="340" rx="15" ry="10" fill="#FFFFFF" fill-opacity="0.7" stroke="#D6D6D6" stroke-width="1" />
      <!-- Stripes -->
      <rect x="370" y="335" width="20" height="5" fill="#F4D7A8" />
      <rect x="370" y="345" width="20" height="5" fill="#F4D7A8" />
      <rect x="370" y="355" width="20" height="5" fill="#F4D7A8" />
      <!-- Flight path -->
      <path d="M380,320 Q360,300 340,305 T310,290" fill="none" stroke="#3F2E23" stroke-width="1.5" stroke-dasharray="2,2" />
    </g>
    
    <!-- Third bee -->
    <g transform="rotate(15, 250, 420)">
      <ellipse cx="250" cy="420" rx="15" ry="25" fill="#3F2E23" />
      <!-- Wings -->
      <ellipse cx="240" cy="410" rx="12" ry="8" fill="#FFFFFF" fill-opacity="0.7" stroke="#D6D6D6" stroke-width="1" />
      <ellipse cx="260" cy="410" rx="12" ry="8" fill="#FFFFFF" fill-opacity="0.7" stroke="#D6D6D6" stroke-width="1" />
      <!-- Stripes -->
      <rect x="245" y="410" width="10" height="3" fill="#F4D7A8" />
      <rect x="245" y="418" width="10" height="3" fill="#F4D7A8" />
      <rect x="245" y="426" width="10" height="3" fill="#F4D7A8" />
      <!-- Flight path -->
      <path d="M250,395 Q270,385 275,365 T290,340" fill="none" stroke="#3F2E23" stroke-width="1.5" stroke-dasharray="2,2" />
    </g>
  </g>
  
  <!-- Small floating pollen particles -->
  <g>
    <circle cx="150" cy="200" r="3" fill="#F8E0A7">
      <animate attributeName="cy" values="200;190;200" dur="5s" repeatCount="indefinite" />
    </circle>
    <circle cx="350" cy="180" r="2" fill="#F8E0A7">
      <animate attributeName="cy" values="180;170;180" dur="4s" repeatCount="indefinite" />
    </circle>
    <circle cx="220" cy="350" r="2.5" fill="#F8E0A7">
      <animate attributeName="cy" values="350;340;350" dur="6s" repeatCount="indefinite" />
    </circle>
    <circle cx="300" cy="100" r="2" fill="#F8E0A7">
      <animate attributeName="cy" values="100;90;100" dur="5.5s" repeatCount="indefinite" />
    </circle>
    <circle cx="400" cy="280" r="3" fill="#F8E0A7">
      <animate attributeName="cy" values="280;270;280" dur="3.5s" repeatCount="indefinite" />
    </circle>
  </g>
</svg>
